#include <vector>

class Solution {
public:
    std::vector<int> runningSum(std::vector<int>& nums) {
        for (int i = 1; i < (int)nums.size(); ++i) {
            nums[i] += nums[i - 1];
        }
        return nums;
    }
};

class Solution {
    public int[] runningSum(int[] nums) {
        for (int i = 1; i < nums.length; i++) {
            nums[i] += nums[i - 1];
        }
        return nums;
    }
}

var runningSum = function(nums) {
    for (let i = 1; i < nums.length; i++) {
        nums[i] += nums[i - 1];
    }
    return nums;
};
